{"action": "replace_code", "code": "def solve(data):
    if not data['durations']:
        return {'duration': 0, 'path': []}

    memo = {}

    def get_best_path(node):
        if node in memo:
            return memo[node]

        duration = data['durations'][node]
        path = [node]

        parents = data['deps'].get(node, [])
        if not parents:
            memo[node] = (duration, path)
            return (duration, path)

        best_parent_result = None
        for parent in parents:
            parent_result = get_best_path(parent)
            if best_parent_result is None:
                best_parent_result = parent_result
            else:
                # Сравнение: сначала по сумме (убывание), затем лексикографически по пути (возрастание)
                # Чтобы выбрать минимальный путь при равных суммах, сравниваем пути напрямую
                if (parent_result[0] > best_parent_result[0]) or \
                   (parent_result[0] == best_parent_result[0] and parent_result[1] < best_parent_result[1]):
                    best_parent_result = parent_result

        total_duration = best_parent_result[0] + duration
        total_path = best_parent_result[1] + path
        memo[node] = (total_duration, total_path)
        return (total_duration, total_path)

    candidates = []
    for node in data['durations']:
        result = get_best_path(node)
        candidates.append(result)

    if not candidates:
        return {'duration': 0, 'path': []}

    # Выбираем максимальную сумму, при равенстве - лексикографически минимальный путь
    best = max(candidates, key=lambda x: (x[0], -x[1]))

    return {'duration': best[0], 'path': best[1]}
