{"action": "replace_code", "code": "def solve(data):
    if not data['durations']:
        return {'duration': 0, 'path': []}

    memo = {}

    def get_best_path(node):
        if node in memo:
            return memo[node]

        duration = data['durations'][node]
        path = [node]

        parents = data['deps'].get(node, [])
        if not parents:
            memo[node] = (duration, path)
            return (duration, path)

        best_cost = -1
        best_path = None

        for parent in parents:
            parent_cost, parent_path = get_best_path(parent)
            new_cost = parent_cost + duration
            new_path = parent_path + [node]

            if new_cost > best_cost or (new_cost == best_cost and (best_path is None or new_path < best_path)):
                best_cost = new_cost
                best_path = new_path

        memo[node] = (best_cost, best_path)
        return (best_cost, best_path)

    candidates = []
    for node in data['durations']:
        cost, path = get_best_path(node)
        candidates.append((cost, path))

    if not candidates:
        return {'duration': 0, 'path': []}

    best_cost, best_path = max(candidates, key=lambda x: (x[0], x[1]))

    return {'duration': best_cost, 'path': best_path}
